import math
t = int(input())
for _ in range(t):
	n = int(input())
	a = list(map(int, input().split()))
	cd = {}
	for i in range(32):
		cd[i] = 0
	counts = [cd]
	for j in range(n):
		newc = counts[j].copy()
		if a[j] != 0:
			digs = int(math.log2(a[j])) + 1
		if a[j] == 0:
			digs = 0
		newc[digs] += 1
		counts.append(newc)
	q = int(input())
	for _ in range(q):
		(l, r, x) = map(int, input().split())
		if x != 0:
			xd = int(math.log2(x)) + 1
		if x == 0:
			xd = 0
		print(r - l + 1 - (counts[r][xd] - counts[l - 1][xd]))
